// Sol/Grok inside a workflow (global rules, 03.11): a cheap Haiku stage delegates through delegate_task and returns the worker's summary.
function extBrief(cat, model, title, task, access) {
  return `Делегируй задачу внешнему воркеру и верни ТОЛЬКО его итог, без своих комментариев.
Вызови инструмент delegate_task (MCP-сервер t3-code) с аргументами:
  category: ${JSON.stringify(cat)}
  model: ${JSON.stringify(model)}
  access​: ${JSON.stringify(access​ || 'read')}
  mode: "wait"
  timeoutMs: 3600000
  title: ${JSON.stringify(title)}
  clientRequestId: ${JSON.stringify('ext-' + title.replace(/[^a-z0-9]+/gi, '-').toLowerCase())}
  task: ${JSON.stringify(task)}
Если ответ пришёл с waitTimedOut=true, задача ещё идёт: проверяй task_status с её taskId раз в ~5 минут (между проверками Bash \`sleep 290\`), пока итог не будет готов, но не дольше 5 часов. Затем верни дословно summary воркера.
Если delegate_task недоступен, вернул ошибку (например model_unavailable) или воркер упал — сам задачу НЕ делай, верни одну строку "EXT_FAIL: <причина>".`
}
const ext = (cat, model, title, task, access​, phaseTitle) =>
  agent(extBrief(cat, model, title, task, access​), { label: `${model}:${title}`.slice(0, 40), phase: phaseTitle, model: 'haiku', effort: 'low' })
// Sol first; if the delegation itself fails, the same task goes to a Sonnet worker.
async function solOrSonnet(title, task, phaseTitle) {
  const r = await ext('implement', 'gpt-6.1-sol', title, task, 'write', phaseTitle)
  if (r && !/^\s*EXT_FAIL/.test(r)) return { by: 'gpt-6.1-sol', text: r }
  const s = await agent(task, { label: `sonnet:${title}`.slice(0, 40), phase: phaseTitle, model: 'sonnet', effort: 'medium' })
  return { by: 'sonnet (fallback: ' + String(r || 'empty').slice(0, 120) + ')', text: s }
}
EOF
